export function evaluateDependencyScenario(graph,scenarioId='normal'){
  const scenario=graph.scenarios.find(s=>s.id===scenarioId);if(!scenario)throw new Error('Unknown dependency scenario: '+scenarioId);
  const all=new Map(graph.nodes.map(n=>[n.id,n])),blocked=new Set(scenario.unavailable),result=new Map(),visiting=new Set();
  const visit=id=>{if(result.has(id))return result.get(id);if(!all.has(id))throw new Error('Unknown dependency node: '+id);if(visiting.has(id))throw new Error('Dependency cycle at '+id);visiting.add(id);
    const missing=graph.edges.filter(e=>e.to===id).map(e=>e.from).filter(id=>!visit(id).available),available=!blocked.has(id)&&missing.length===0;
    const record={...all.get(id),available,reason:blocked.has(id)?'Unavailable in the selected example':missing.length?'Missing: '+missing.map(id=>all.get(id).label).join(', '):'All declared prerequisites present'};visiting.delete(id);result.set(id,record);return record;};
  return graph.nodes.map(n=>visit(n.id));
}
export function buildPointTrace(scenario='current'){
  if(!['current','delayed','mismatched','uncertain'].includes(scenario))throw new Error('Unknown point scenario: '+scenario);
  const expected='DEMO.AHU01.DAMPER.POS',source={pointId:scenario==='mismatched'?'DEMO.AHU02.DAMPER.POS':expected,value:65,units:'%',sourceTime:12.4,quality:scenario==='uncertain'?'Uncertain':'Good'};
  const received={...source,receivedTime:scenario==='delayed'?28:12.6},displayTime=received.receivedTime+.4;
  return {scenario,expected,source,received,displayTime,age:displayTime-source.sourceTime,identityMatches:source.pointId===expected,interpretation:scenario==='mismatched'?'Identity differs: do not substitute this value for the selected point.':scenario==='delayed'?'This sample arrived late. Its source time stays unchanged; a Good quality status alone does not establish that it is recent enough for the application.':scenario==='uncertain'?'Retain the qualified status alongside the value.':'The point identity matches. Read the source time, arrival time and Good quality status as separate information.',boundary:'Sample values with elapsed times in seconds. Age is measured from this sample’s source time; an acceptable age depends on the application.'};
}
